class _CalGrid extends StatelessWidget {
  const _CalGrid({required this.p, required this.s, required this.days,
      required this.firstWeekday, required this.today, required this.marked});

  final DesignPalette p;
  final _Strings s;
  final int days;
  final int firstWeekday;
  final int today;
  final List<int> marked;

  @override
  Widget build(BuildContext context) {
    final int rows = ((firstWeekday + days - 1) ~/ 7) + 1;
    return Column(
      children: <Widget>[
        Row(
          children: List<Widget>.generate(7, (int i) {
            return Expanded(
              child: Center(
                child: Text(
                    [s.calWk0, s.calWk1, s.calWk2, s.calWk3, s.calWk4, s.calWk5,
                        s.calWk6][i],
                    style: TextStyle(fontSize: 10.5, color: p.dim)),
              ),
            );
          }),
        ),
        const SizedBox(height: 6),
        for (int r = 0; r < rows; r++)
          Row(
            children: List<Widget>.generate(7, (int c) {
              final int idx = r * 7 + c;
              final int d = idx - firstWeekday + 1;
              final bool inRange = d >= 1 && d <= days;
              final bool isToday = inRange && d == today;
              return Expanded(
                child: SizedBox(
                  height: 40,
                  child: inRange
                      ? Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: <Widget>[
                            Container(
                              width: 30,
                              height: 30,
                              alignment: Alignment.center,
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                color: isToday ? p.primary : Colors.transparent,
                              ),
                              child: Text('$d',
                                  style: TextStyle(
                                      fontSize: 12,
                                      fontWeight: isToday
                                          ? FontWeight.w600
                                          : FontWeight.w400,
                                      color: isToday ? p.onPrimary : p.text)),
                            ),
                            if (marked.contains(d))
                              Container(
                                width: 4,
                                height: 4,
                                decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    color: isToday ? p.onPrimary : p.accent),
                              )
                            else
                              const SizedBox(height: 4),
                          ],
                        )
                      : const SizedBox.shrink(),
                ),
              );
            }),
          ),
      ],
    );
  }
}

